function addDays(d,n){const x=new Date(d+'T12:00:00');x.setDate(x.getDate()+n);return x.toISOString().slice(0,10)}
function schoolDays(n){const out=[];let d=today();while(out.length<n){const w=new Date(d+'T12:00:00').getDay();if(w>0&&w<6)out.unshift(d);d=addDays(d,-1)}return out}
