 S.staff=[{id:'X1',name:'Mr. Daniel Flomo (Demo)',role:'Principal',phone:'+231 770 000 201',salary:600},{id:'X2',name:'Mrs. Grace Toe (Demo)',role:'Accountant/Bursar',phone:'+231 770 000 202',salary:450},{id:'X3',name:'Ms. Musu Dolo (Demo)',role:'Librarian',phone:'+231 770 000 203',salary:220},{id:'X4',name:'Mr. Moses Wolo (Demo)',role:'Security',phone:'+231 770 000 204',salary:180}];
 S.parents=[{id:'P1',name:'Mrs. Esther Johnson (Demo)',phone:'+231 880 000 301'},{id:'P2',name:'Mr. Samuel Doe (Demo)',phone:'+231 880 000 302'},{id:'P3',name:'Other parents (Demo)',phone:'+231 880 000 399'}];
 S.students=[];let n=1;
 CLASSES.forEach(c=>{for(let k=0;k<3;k++){S.students.push({id:'SF'+String(n).padStart(4,'0'),name:FN[ri(0,FN.length-1)]+' '+LN[ri(0,LN.length-1)],cls:c,gender:rnd()<.5?'F':'M',dob:(2026-CLASSES.indexOf(c)-4)+'-0'+ri(1,9)+'-1'+ri(0,9),parent:'P3'});n++}});
 const set=(i,name,p)=>{S.students[i].name=name;S.students[i].parent=p};
 const g9=CLASSES.indexOf('Grade 9')*3;
 set(g9,'Victor Johnson','P1');set(CLASSES.indexOf('Grade 3')*3,'Zoe Johnson','P1');set(g9+1,'Martha Doe','P2');
 S.grades={};S.students.forEach(s=>{const base=ri(62,92);S.grades[s.id]={};subjectsFor(s.cls).forEach(sub=>{S.grades[s.id][sub]={};PERIODS.slice(0,5).forEach(([p])=>S.grades[s.id][sub][p]=Math.max(50,Math.min(99,base+ri(-12,10))))})});
 S.att={};schoolDays(20).forEach(d=>{S.att[d]={};S.students.forEach(s=>{const r=rnd();S.att[d][s.id]=r<.88?'P':r<.95?'L':'A'})});
 S.students.forEach(s=>{const fee=feeFor(s.cls),k=ri(0,3);for(let i=0;i<k;i++){S.payments.push({id:'RC'+(1000+S.payments.length),sid:s.id,amt:Math.round(fee/3),date:addDays(today(),-ri(5,60)),method:['Cash','Mobile Money (Orange)','Mobile Money (MTN)','Bank'][ri(0,3)],by:'bursar'})}});
 S.plans=S.students.map(s=>({sid:s.id,plan:'3 instalments',due:[addDays(today(),-40),addDays(today(),20),addDays(today(),80)]}));
 S.admissions=[{id:'AP1',name:'Kebeh Nyumah (Sample)',cls:'Grade 7',parent:'Mr. Nyumah',phone:'+231 770 111 222',date:addDays(today(),-3),status:'New'},{id:'AP2',name:'Isaac Tarpeh (Sample)',cls:'K1',parent:'Mrs. Tarpeh',phone:'+231 886 333 444',date:addDays(today(),-8),status:'Interview scheduled'}];
 S.homework=[{id:'H1',cls:'Grade 9',subj:'Mathematics',title:'Algebra exercise 4.2 (Sample)',due:addDays(today(),3),by:'T1'},{id:'H2',cls:'Grade 3',subj:'English',title:'Read story p.12 and write 5 sentences (Sample)',due:addDays(today(),2),by:'T2'}];
 S.discipline=[{id:'D1',sid:S.students[g9].id,date:addDays(today(),-6),type:'Commendation',desc:'Helped organise class library (Sample)',action:'Certificate',by:'T1',status:'approved'},{id:'D2',sid:S.students[g9+1].id,date:addDays(today(),-2),type:'Late arrival',desc:'Late three times this week (Sample)',action:'Parent informed',by:'T1',status:'pending'}];
 S.library=[{id:'B1',title:'Things Fall Apart',type:'Book',qty:12,out:3},{id:'B2',title:'WAEC Mathematics Past Questions',type:'Book',qty:20,out:8},{id:'B3',title:'Science lab microscopes',type:'Inventory',qty:4,out:0},{id:'B4',title:'Football (sports)',type:'Inventory',qty:10,out:2}];
 const E=(title,cat,date,aud,extra={})=>S.events.push(Object.assign({id:'E'+(S.events.length+1),title,cat,date,time:'',aud,cls:'',recur:'none',status:'approved',sample:true,by:'proprietor'},extra));
 E('PTA General Meeting (Sample date)','PTA',addDays(today(),1),'all_parents',{time:'10:00'});
 E('1st Semester Exams begin (Sample)','Exam',addDays(today(),14),'everyone');
