 if(comp){const tos=t?[['all_teachers','All instructors'],['class',"My class's parents"],['parents','Specific parents (my classes)']]:[['all_teachers','All instructors'],['all_parents','All parents'],['class',"A class's parents"],['parents','Specific parents']];const ps=t?S.parents.filter(p=>S.students.some(s=>s.parent===p.id&&cl.includes(s.cls))):S.parents;
 h+=`<div class="card"><h3>Compose message / reminder</h3><p class="muted">Messages and reminders go into a <b>pending queue</b> and are only sent after Proprietor approval.</p><div class="row"><div><label>Type</label><select id="mk">${opts([['message','Message'],['reminder','Reminder']])}</select></div><div><label>Reminder topic</label><select id="mt">${opts(['General','PTA meeting','Exams','Event'])}</select></div><div><label>Send to</label><select id="mto">${opts(tos)}</select></div></div>
 <div class="row"><div id="mcw"><label>Class</label><select id="mc">${opts(cl)}</select></div><div id="mpw"><label>Parents (Ctrl/⌘ for several)</label><select id="mp" multiple size="3">${opts(ps.map(p=>[p.id,p.name]))}</select></div></div><label>Subject</label><input id="ms"><label>Message</label><textarea id="mb" rows="3"></textarea><button class="btn" id="msend" style="margin-top:.6rem">Submit for approval</button></div>
 <div class="card tw"><h3>${t?'My submitted messages':'Queue & history'}</h3><table><tr><th>Submitted</th><th>Type</th><th>To</th><th>Subject</th><th>Status</th></tr>${S.queue.filter(q=>!t||q.by===ME.u).map(q=>`<tr><td>${new Date(q.at).toLocaleDateString()}</td><td>${q.kind}${q.topic?' · '+q.topic:''}</td><td>${esc(toLabel(q.to))}</td><td>${esc(q.subject)}</td><td><span class="tag ${q.status==='pending'?'y':q.status==='rejected'?'r':''}">${q.status}</span></td></tr>`).join('')}</table></div>`}
 m.innerHTML=h;if(!comp)return;const tg=()=>{$('#mcw').style.display=$('#mto').value==='class'?'':'none';$('#mpw').style.display=$('#mto').value==='parents'?'':'none'};$('#mto').onchange=tg;tg();
